package com.grievancecampus.servlet;
import javax.servlet.ServletException;import javax.servlet.http.*;import java.io.IOException;import java.sql.SQLException;import com.grievancecampus.dao.UserDAO;import com.grievancecampus.model.User;
public class UserManagementServlet extends HttpServlet {
 protected void doGet(HttpServletRequest r,HttpServletResponse p)throws IOException,ServletException{if(!admin(r,p))return;try{r.setAttribute("users",new UserDAO().list());r.getRequestDispatcher("/admin/users.jsp").forward(r,p);}catch(SQLException e){getServletContext().log("User list query failed",e);p.sendError(500);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{if(!admin(r,p))return;String name=clean(r.getParameter("name")),email=clean(r.getParameter("email")).toLowerCase(java.util.Locale.ROOT),password=r.getParameter("password"),role=clean(r.getParameter("role")),department=clean(r.getParameter("department")),section=clean(r.getParameter("section")),jobTitle=clean(r.getParameter("jobTitle"));if(name.isEmpty()||name.length()>120||!com.grievancecampus.util.ValidationUtil.validEmail(email)||password==null||password.length()<8||password.length()>255||!java.util.Arrays.asList("TEACHER","CLASS_TEACHER","HOD","STAFF","ADMIN").contains(role)||jobTitle.length()>80){p.sendRedirect(r.getContextPath()+"/app/users?error=validation");return;}if("STAFF".equals(role)&&jobTitle.isEmpty()){p.sendRedirect(r.getContextPath()+"/app/users?error=validation");return;}try{new UserDAO().create(name,email,password,role,department.isEmpty()?null:department,section.isEmpty()?null:section,jobTitle.isEmpty()?null:jobTitle);p.sendRedirect(r.getContextPath()+"/app/users?saved=1");}catch(SQLException e){getServletContext().log("User creation failed",e);p.sendRedirect(r.getContextPath()+"/app/users?error=save");}}
 private boolean admin(HttpServletRequest r,HttpServletResponse p)throws IOException{User u=(User)r.getSession().getAttribute("user");if(u==null||!"ADMIN".equals(u.getRole())){p.sendError(403);return false;}return true;}
 private String clean(String s){return s==null?"":s.trim();}
}
